/**
 * Illustrated performer artwork for the 2D Sketch stage.
 *
 * The PNGs in public/cast/ are generated by scripts/gen-cast-art.mjs and are
 * deliberately mouthless: the renderer draws the mouth itself so it can follow
 * the voice. castArt.json carries the measurements that make that possible -
 * where the mouth belongs, how big the face is, and which flat colours the
 * illustration was drawn with.
 */
import castArt from './castArt.json';

export interface CastArtPoint {
  /** Fraction of the artwork's width, from its left edge. */
  x: number;
  /** Fraction of the artwork's height, from its top edge. */
  y: number;
}

export interface CastArtwork {
  image: string;
  width: number;
  height: number;
  anchors: {
    mouth: CastArtPoint;
    noseBase: CastArtPoint;
    chin: CastArtPoint;
    leftEye: CastArtPoint;
    rightEye: CastArtPoint;
  };
  palette: {
    skin: string;
    skinShadow: string;
    ink: string;
    mouth: string;
    tongue: string;
    teeth: string;
  };
}

const ARTWORK = castArt as Record<string, CastArtwork>;

/**
 * Artwork for a character. Scripts can name anyone, so unknown characters
 * borrow the performer of their gender rather than losing their face.
 */
export function artworkFor(name: string, gender: 'male' | 'female'): CastArtwork {
  return ARTWORK[name.trim().toLowerCase()] ?? ARTWORK[gender === 'female' ? 'sienna' : 'marcus'];
}
